+// Returns a new session whose expiry starts from now; the input is not mutated.
+export function refreshSession(session: Session, ttlMs = DEFAULT_TTL_MS): Session {
+  const now = Date.now();
+  return { ...session, expiresAt: now + ttlMs };
+}
+
+export function isExpired(session: Session, leewayMs = 0, now = Date.now()): boolean {
+  return now > session.expiresAt + leewayMs;
